# The tool layer the agent calls. Do not change the three names or signatures.

INVENTORY = {"SKU-1": 4, "SKU-2": 0}
BUDGETS = {"ops": 500, "eng": 0}


def reserve_stock(sku: str, qty: int) -> dict:
    if sku not in INVENTORY:
        return {"ok": False, "error": "failed"}
    if INVENTORY[sku] < qty:
        return {"ok": False, "error": "failed"}
    INVENTORY[sku] -= qty
    return {"ok": True}


def charge_budget(team: str, amount: int) -> dict:
    if team not in BUDGETS:
        return {"ok": False, "error": "failed"}
    if BUDGETS[team] < amount:
        return {"ok": False, "error": "failed"}
    BUDGETS[team] -= amount
    return {"ok": True}


def submit_order(sku: str, team: str, qty: int) -> dict:
    r = reserve_stock(sku, qty)
    if not r["ok"]:
        return {"ok": False, "error": "failed"}
    c = charge_budget(team, qty * 10)
    if not c["ok"]:
        return {"ok": False, "error": "failed"}
    return {"ok": True}

