import time


class Response:
    def __init__(self, status, body):
        self.status = status
        self.body = body


class Transport:
    """Injected for tests. call() returns a Response or raises."""

    def __init__(self, statuses):
        self._statuses = list(statuses)
        self.calls = 0
        self.sleeps = []

    def call(self, path):
        self.calls += 1
        status = self._statuses.pop(0) if self._statuses else 200
        return Response(status, {"path": path})


def fetch(transport: Transport, path: str, sleep=time.sleep) -> Response:
    """Return the response. Currently gives up on the first failure."""
    return transport.call(path)
